import { expect } from '@esm-bundle/chai';
// DOM nodes are compared as booleans: a failing chai assertion carrying DOM nodes hangs the runner.
// NO static import of the component: <td-action-button> is defined LATE (dynamic import below), after the no-JS checks.

// v0.36.0 (plan QĐ 14) — td_action_button() / <td-action-button> hydrate in place, contract `action-button@1`, in
// Chromium, Firefox AND WebKit. The markup is EXACTLY what php/td.php prints for every preset + every case of
// test/ssr/action-button.fixtures.json: test/ssr/fixtures/action-button.html, generated by
// `node test/ssr/build-action-button-fixture.mjs` and kept fresh by test/php/td-action-button.test.js.
const link = document.createElement('link');
link.rel = 'stylesheet';
link.href = '/td.css';
document.head.appendChild(link);
await new Promise((r) => { link.onload = r; link.onerror = r; });

const FIXTURE = await (await fetch('/test/ssr/fixtures/action-button.html')).text();
const TPL = document.createElement('template');
TPL.innerHTML = FIXTURE;
const root = document.createElement('div');
root.innerHTML = FIXTURE;
document.body.appendChild(root);
const IDS = [...root.querySelectorAll('section[data-case]')].map((s) => s.dataset.case);
const hostOf = (id, r = root) => r.querySelector(`section[data-case="${id}"] > td-action-button`);
const hostHtml = (id) => hostOf(id, TPL.content).outerHTML;

// Tampered markup → never adopted (safe render).
const edit = hostHtml('preset-edit');
const MM = {
  'mm-schema': edit.replace('action-button@1', 'action-button@2'),
  'mm-button-marker': edit.replace('action-button@1', 'button@1'),
  'mm-label': edit.replace(/aria-label="Chỉnh sửa" data-tooltip="Chỉnh sửa"/, 'aria-label="Khác" data-tooltip="Khác"'),
  'mm-tooltip': edit.replace('data-tooltip="Chỉnh sửa"', 'data-tooltip="Khác"'),
  'mm-icon': edit.replace('data-td-icon="pencil"', 'data-td-icon="trash"'),
  'mm-onclick': edit.replace('<button ', '<button onclick="window.__pwnedAb = 1" '),
  'mm-formaction': edit.replace('<button ', '<button formaction="https://attacker.example/" '),
  'mm-label-span': edit.replace('<span class="td-btn__spinner', '<span class="td-btn__label">Chỉnh sửa</span><span class="td-btn__spinner'),
  'mm-tag': edit.replace('action="edit"', 'action="edit" href="/x"'),
  'mm-host-aria': edit.replace('action="edit"', 'action="edit" aria-label="Sửa bài 9"'),
};
const mismatch = document.createElement('div');
mismatch.innerHTML = Object.entries(MM).map(([id, html]) => `<section data-case="${id}">${html}</section>`).join('');
document.body.appendChild(mismatch);

/** Order-independent serialisation; `ignore` = attributes the tooltip / runtime may add or remove (title, describedby). */
function serial(node, ignore = ['title', 'aria-describedby']) {
  if (node.nodeType === Node.TEXT_NODE) return node.data.trim() ? `#${node.data}` : '';
  if (node.nodeType !== Node.ELEMENT_NODE) return '';
  const attrs = [...node.attributes].filter((a) => !ignore.includes(a.name)).map((a) => `${a.name}=${JSON.stringify(a.value)}`).sort();
  return `<${node.localName} ${attrs.join(' ')}>${[...node.childNodes].map((n) => serial(n)).join('')}</${node.localName}>`;
}

const before = new Map();
for (const id of IDS) {
  const c = hostOf(id).querySelector(':scope > .td-btn');
  before.set(id, { node: c, serial: serial(c), rect: c.getBoundingClientRect() });
}
const mmBefore = new Map(Object.keys(MM).map((id) => [id, hostOf(id, mismatch).querySelector(':scope > .td-btn')]));
const noJsWidth = before.get('preset-edit').rect.width;

const { TdActionButton } = await import('./td-action-button.js');
await customElements.whenDefined('td-action-button');

describe('td-action-button SSR (action-button@1)', () => {
  it('no JS: the PHP control is already the 36 px square with its icon', () => {
    expect(Math.abs(noJsWidth - 36)).to.be.below(0.5);
  });

  it('every fixture case is adopted IN PLACE (same node), markup unchanged, marker consumed', () => {
    expect(IDS.length).to.be.at.least(23 + 20);
    for (const id of IDS) {
      const h = hostOf(id);
      const c = h.querySelector(':scope > .td-btn');
      expect(c === before.get(id).node, `${id}: same node`).to.equal(true);
      expect(serial(c), id).to.equal(before.get(id).serial);
      expect(h.hasAttribute('data-td-ssr'), id).to.equal(false);
    }
  });

  it('a JS-rendered twin of each case has the same markup (PHP == render() + _syncState())', () => {
    const twin = document.createElement('div');
    document.body.appendChild(twin);
    for (const id of IDS) {
      const src = hostOf(id, TPL.content);
      const h = document.createElement('td-action-button');
      for (const a of src.attributes) if (a.name !== 'data-td-ssr') h.setAttribute(a.name, a.value);
      twin.appendChild(h);
      // site pass-through attributes (attrs option) exist only in the PHP markup
      const ign = ['title', 'aria-describedby', 'data-row'];
      expect(serial(h.querySelector(':scope > .td-btn'), ign), id).to.equal(serial(before.get(id).node, ign));
    }
    twin.remove();
  });

  it('XSS label stays text; site attrs: onclick / style / data-td-icon never printed', () => {
    const x = hostOf('xss').querySelector('.td-btn');
    expect(x.querySelector('img')).to.equal(null);
    expect(window.__pwned).to.equal(undefined);
    const s = hostOf('site-attrs');
    expect(s.id).to.equal('ab-1');
    const c = s.querySelector('.td-btn');
    for (const a of ['onclick', 'style', 'data-td-icon']) expect(c.hasAttribute(a), a).to.equal(false);
  });

  it('tampered markup → rendered safely (new node), never the server attributes', () => {
    for (const id of Object.keys(MM)) {
      const h = hostOf(id, mismatch);
      const c = h.querySelector(':scope > .td-btn');
      expect(!!c, id).to.equal(true);
      expect(c === mmBefore.get(id), `${id}: re-rendered`).to.equal(false);
      for (const a of ['onclick', 'formaction']) expect(c.hasAttribute(a), `${id} ${a}`).to.equal(false);
      expect(c.querySelector('.td-btn__label'), id).to.equal(null);
    }
    expect(hostOf('mm-host-aria', mismatch).querySelector('.td-btn').getAttribute('aria-label')).to.equal('Sửa bài 9');
    expect(hostOf('mm-tag', mismatch).querySelector('.td-btn').localName).to.equal('a');
    expect(window.__pwnedAb).to.equal(undefined);
  });

  it('SSR host aria-label: adopted when the control carries that name', () => {
    const h = hostOf('aria-label');
    expect(h.querySelector('.td-btn') === before.get('aria-label').node).to.equal(true);
    expect(h.querySelector('.td-btn').getAttribute('aria-label')).to.equal('Sửa bài số 1');
    expect(TdActionButton.SSR_SCHEMA).to.equal(1);
  });
});
